fn font_shape_shared_original_mark_anchors(){let rows:serde_json::Value=serde_json::from_str(include_str!("../🧵️shape/📍️mark/🧫️fixtures/🔣️.json")).unwrap();let mut admission=FontFaceAdmissionJob::new(bytes("🚀️anta/🏛️latin/📖️regular"),FontOutlineLimits::default());while !admission.advance(4096).unwrap().done{}let font=admission.take_result().unwrap();let parsed=ttf_parser::Face::parse(&font.source,0).unwrap();let mut plan=shape::FontLookupPlanCursor::new(font.face,false,*b"latn",&[*b"mark"],1000000000);while !plan.advance(&font.source,4096).unwrap().done{}let lookups=plan.take_result().unwrap();for lookup in lookups.iter(){let foreign=parsed.tables().gpos.unwrap().lookups.get(lookup.index).unwrap();for row in rows.as_array().unwrap(){let base=ttf_parser::GlyphId(row["base"].as_u64().unwrap()as u16);let mark=ttf_parser::GlyphId(row["mark"].as_u64().unwrap()as u16);let expected=(0..foreign.subtables.len()).find_map(|at|{let ttf_parser::gpos::PositioningSubtable::MarkToBase(table)=foreign.subtables.get(at)?else{return None;};let mark_index=table.mark_coverage.get(mark)?;let base_index=table.base_coverage.get(base)?;let(class,anchor)=table.marks.get(mark_index)?;let reference=table.anchors.get(base_index,class)?;Some(shape::mark::FontMarkAttachment{x:i32::from(reference.x)-i32::from(anchor.x),y:i32::from(reference.y)-i32::from(anchor.y)})});let golden=row["attachment"].as_array().map(|values|shape::mark::FontMarkAttachment{x:values[0].as_i64().unwrap()as i32,y:values[1].as_i64().unwrap()as i32});assert_eq!(expected,golden);for grant in [1,7,4096]{let mut cursor=shape::mark::FontMarkCursor::new(font.face,*lookup,base.0,mark.0,1000000000);while !cursor.advance(&font.source,grant).unwrap().done{}assert_eq!(cursor.result().unwrap(),expected);close(cursor);}for stop in [0,1,2,7,20,40,100]{let mut cursor=shape::mark::FontMarkCursor::new(font.face,*lookup,base.0,mark.0,1000000000);if stop>0{cursor.advance(&font.source,stop).unwrap();}cursor.cancel();assert!(cursor.result().is_err());close(cursor);}}}close(plan);close(lookups);close(admission);close(font);println!("[DEBUG] Shared mark anchor corpus independently matches original ttf-parser GPOS, all grants, seven cancellation stages and allocator-matched physical close");}
