fn font_run_original_shaped_cluster_outlines(){use shape::unicode::*;let mut rows:serde_json::Value=serde_json::from_str(include_str!("../🧵️shape/🧵️layout/🧫️fixtures/🔣️.json")).unwrap();let run_rows:serde_json::Value=serde_json::from_str(include_str!("../🧵️run/🧫️fixtures/🔣️.json")).unwrap();rows.as_array_mut().unwrap().extend(run_rows.as_array().unwrap().iter().cloned());let mut unicode_admission=UnicodeDataAdmissionJob::new(UNICODE_BYTES.to_vec(),1000000);while !unicode_admission.advance(4096).unwrap().done{}let data=unicode_admission.take_result().unwrap();for row in rows.as_array().unwrap(){let mut admission=FontFaceAdmissionJob::new(bytes(row["font"].as_str().unwrap()),FontOutlineLimits::default());while !admission.advance(4096).unwrap().done{}let font=admission.take_result().unwrap();let text=row["text"].as_str().unwrap();let oracle_text=row["oracleText"].as_str().unwrap_or(text);let source_offset=text.find(oracle_text).unwrap();let mut buffer=rustybuzz::UnicodeBuffer::new();for(at,scalar)in oracle_text.char_indices(){buffer.add(scalar,(source_offset+at)as u32);}buffer.guess_segment_properties();if row["oracleDirection"].as_str()==Some("rtl"){buffer.set_direction(rustybuzz::Direction::RightToLeft);}let oracle=rustybuzz::shape(&rustybuzz::Face::from_slice(&font.source,0).unwrap(),&[],buffer);println!("[DEBUG] Original composed oracle {} {:?} {:?}",row["name"],oracle.glyph_infos(),oracle.glyph_positions());let style=run::FontRunStyle{size:40.0,origin:[8.0,8.0],line_height:1.2,kerning:true};for grant in [1,7,4096]{let mut cursor=run::FontOutlineRunCursor::new(text,1,style,FontOutlineLimits::default(),data.layout,&data.source);let mut work=0;loop{let p=cursor.advance(text,std::slice::from_ref(&font),&data.source,grant).unwrap();assert!(p.work-work<=grant as u64);work=p.work;if p.done{break;}assert!(cursor.result().is_err());}let output=cursor.take_result().unwrap();let ignore=row["ignorableGlyphs"].as_array();let visible=oracle.glyph_infos().iter().zip(oracle.glyph_positions()).filter(|(glyph,_)|!ignore.is_some_and(|values|values.iter().any(|value|value.as_u64()==Some(u64::from(glyph.glyph_id))))).collect::<Vec<_>>();assert_eq!(output.glyphs.len(),visible.len());if let Some(glyphs)=row["glyphs"].as_array(){assert_eq!(visible.iter().map(|(glyph,_)|u64::from(glyph.glyph_id)).collect::<Vec<_>>(),glyphs.iter().map(|value|value.as_u64().unwrap()).collect::<Vec<_>>());}if let Some(positions)=row["positions"].as_array(){assert_eq!(visible.iter().map(|(_,position)|[i64::from(position.x_advance),i64::from(position.x_offset),i64::from(position.y_offset)]).collect::<Vec<_>>(),positions.iter().map(|value|[value[0].as_i64().unwrap(),value[1].as_i64().unwrap(),value[2].as_i64().unwrap()]).collect::<Vec<_>>());}let scale=style.size/f64::from(font.face.units_per_em);let mut pen=0.0;for(actual,(glyph,position))in output.glyphs.iter().zip(visible){assert_eq!(actual.glyph,u16::try_from(glyph.glyph_id).unwrap());assert_eq!(actual.source_at,glyph.cluster as usize);assert!((actual.origin[0]-(style.origin[0]+pen+f64::from(position.x_offset)*scale)).abs()<1e-9);assert!((actual.origin[1]-(style.origin[1]+style.size-f64::from(position.y_offset)*scale)).abs()<1e-9);pen+=f64::from(position.x_advance)*scale;}assert!((output.advance-pen).abs()<1e-9);close(cursor);close(output);}for stop in [0,1,2,7,100,1000,10000]{let mut cursor=run::FontOutlineRunCursor::new(text,1,style,FontOutlineLimits::default(),data.layout,&data.source);if stop>0{cursor.advance(text,std::slice::from_ref(&font),&data.source,stop).unwrap();}cursor.cancel();assert!(cursor.result().is_err());close(cursor);}close(admission);close(font);println!("[DEBUG] Native actual outline run {}: composed GSUB glyph IDs, original UTF8 clusters, actual Rustybuzz origins/advances, all grants and seven original physical interruption receipts",row["name"]);}close(unicode_admission);close(data);}
