fn font_shape_active_table_inventory(){for source in catalog::FONT_SOURCES.iter(){let mut admission=FontFaceAdmissionJob::new(source.bytes,FontOutlineLimits::default());while !admission.advance(4096).unwrap().done{}let font=admission.take_result().unwrap();for script in [*b"latn",*b"DFLT"]{let mut cursor=shape::FontLookupPlanCursor::new(font.face,true,script,&[*b"ccmp",*b"rlig",*b"liga",*b"clig",*b"calt"],1000000000);while !cursor.advance(source.bytes.0,4096).unwrap().done{}let result=cursor.take_result().unwrap();println!("[DEBUG] Active GSUB {}/{} {}: {:?}",source.family,source.id,String::from_utf8(script.to_vec()).unwrap(),result.iter().map(|lookup|(lookup.index,lookup.kind,lookup.flags)).collect::<Vec<_>>());close(cursor);close(result);}if source.family=="Anta"&&source.id=="latin-ext"{let parser=ttf_parser::Face::parse(source.bytes.0,0).unwrap();let table=parser.tables().gsub.unwrap();for index in 0..table.lookups.len(){let lookup=table.lookups.get(index).unwrap();for sub in 0..lookup.subtables.len(){if let Some(ttf_parser::gsub::SubstitutionSubtable::Multiple(table))=lookup.subtables.get(sub){for scalar in (0x100..0x300).filter_map(char::from_u32){if let Some(glyph)=parser.glyph_index(scalar){if let Some(index)=table.coverage.get(glyph){let output=table.sequences.get(index).unwrap().substitutes.into_iter().map(|glyph|(glyph.0,parser.tables().gdef.and_then(|table|table.glyph_class(glyph)))).collect::<Vec<_>>();println!("[DEBUG] Original scalar multiple candidate {scalar:?} {glyph:?} => {output:?}");}}}}}}}close(admission);close(font);}}
