fn font_shape_single_multiple_original_substitutions(){let rows:serde_json::Value=serde_json::from_str(include_str!("../🧵️shape/🪄️substitute/🧫️fixtures/🔣️.json")).unwrap();let mut matched=0;for source in catalog::FONT_SOURCES.iter(){let mut admission=FontFaceAdmissionJob::new(source.bytes,FontOutlineLimits::default());while !admission.advance(4096).unwrap().done{}let font=admission.take_result().unwrap();let parsed=ttf_parser::Face::parse(source.bytes.0,0).unwrap();if let Some(table)=parsed.tables().gsub{let r=FontReader::new(source.bytes.0,font.face.gsub.unwrap()).unwrap();let list=font.face.gsub.unwrap().offset+usize::from(r.u16(font.face.gsub.unwrap().offset+8).unwrap());for index in 0..table.lookups.len(){let lookup=table.lookups.get(index).unwrap();let offset=list+usize::from(r.u16(list+2+usize::from(index)*2).unwrap());let kind=r.u16(offset).unwrap();let Some(row)=rows.as_array().unwrap().iter().find(|row|row["kind"].as_u64()==Some(u64::from(kind)))else{continue;};if lookup.flags.0!=0{continue;}let actual=shape::FontLookup{index,kind,flags:lookup.flags.0,offset,subtables:usize::from(lookup.subtables.len())};let first=lookup.subtables.get::<ttf_parser::gsub::SubstitutionSubtable>(0).unwrap();let covered=(0..font.face.glyphs).filter(|glyph|first.coverage().get(ttf_parser::GlyphId(*glyph)).is_some()).collect::<Vec<_>>();for probe in row["probes"].as_array().unwrap(){let glyph=match probe.as_str().unwrap(){"first"=>covered[0],"middle"=>covered[covered.len()/2],"last"=>*covered.last().unwrap(),_=>65535};let expected=(0..lookup.subtables.len()).find_map(|sub|{let sub=lookup.subtables.get::<ttf_parser::gsub::SubstitutionSubtable>(sub).unwrap();match sub{ttf_parser::gsub::SubstitutionSubtable::Single(table)=>table.coverage().get(ttf_parser::GlyphId(glyph)).map(|coverage|match table{ttf_parser::gsub::SingleSubstitution::Format1{delta,..}=>vec![glyph.wrapping_add(delta as u16)],ttf_parser::gsub::SingleSubstitution::Format2{substitutes,..}=>vec![substitutes.get(coverage).unwrap().0]}),ttf_parser::gsub::SubstitutionSubtable::Multiple(table)=>table.coverage.get(ttf_parser::GlyphId(glyph)).map(|coverage|table.sequences.get(coverage).unwrap().substitutes.into_iter().map(|glyph|glyph.0).collect::<Vec<_>>()),_=>panic!("Unexpected original substitution kind")}});for grant in [1,7,4096]{let mut cursor=shape::substitute::FontSubstitutionCursor::new(font.face,actual,glyph,1000000000);let mut work=0;loop{let p=cursor.advance(source.bytes.0,grant).unwrap();assert!(p.work-work<=grant as u64);work=p.work;if p.done{break;}assert!(cursor.result().is_err());}let result=cursor.result().unwrap().map(|result|result.glyphs[..result.count].to_vec());assert_eq!(result,expected);close(cursor);matched+=1;}for stop in [0,1,2,7,20,40,100]{let mut cursor=shape::substitute::FontSubstitutionCursor::new(font.face,actual,glyph,1000000000);if stop>0{cursor.advance(source.bytes.0,stop).unwrap();}let(_,physical)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.cancel());assert_eq!((physical.requested_bytes,physical.released_bytes),(0,0));assert!(cursor.result().is_err());close(cursor);}}}}close(admission);close(font);}assert!(matched>0);println!("[DEBUG] Native original GSUB single/multiple matches={matched}: shared probes, independent ttf-parser, grants1/7/4096, seven interruption stages and actual physical receipts");}
fn bytes(font:&str)->Vec<u8>{let path=std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../..").join("🖼️assets/🔤️fonts").join(font).join("🔤️outline.ttf");std::fs::read(path).unwrap()}
fn close<T:RetireOwned>(value:T)->usize{close_with_items(value,1)}
fn close_with_items<T:RetireOwned>(value:T,items:usize)->usize{let mut owner=ControlledRetirement::new(value).unwrap_or_else(|(error,_)|panic!("{error}"));let mut released=0;for _ in 0..if items>1{10000000}else{2000000}{if owner.terminal_is_empty(){break;}let copy=owner.next_copy_byte_demand().unwrap();let release=owner.next_release_byte_demand().unwrap();let grant=RetainedCloneGrant{maximum_items:items,maximum_copy_bytes:copy,maximum_capacity_bytes:owner.next_capacity_byte_demand(if copy>0{copy}else{release}).unwrap(),maximum_release_bytes:release,maximum_depth:owner.next_depth_demand().unwrap()};let(zero,physical)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.step(RetainedCloneGrant{maximum_items:0,..grant}).unwrap());assert!(!physical.overflowed);assert_eq!((physical.requested_bytes,physical.released_bytes),(0,0));assert!(matches!(zero,RetainedCloneStep::Progress(p)if p==Default::default()));let(step,physical)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.step(grant).unwrap());let(RetainedCloneStep::Progress(receipt)|RetainedCloneStep::Complete(receipt))=step;assert!(receipt.fits(grant));assert!(!physical.overflowed);assert_eq!(physical.requested_bytes,receipt.retained_capacity_bytes);assert_eq!(physical.released_bytes,receipt.released_bytes);released+=physical.released_bytes;}assert!(owner.terminal_is_empty());let(_,physical)=semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(owner));assert_eq!(physical.released_bytes,0);released}
#[test]
fn font_admission_shared_unicode_and_metrics_match_ttf_parser(){let rows:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();for row in rows.as_array().unwrap(){for grant in [1,7,4096]{let source=bytes(row["font"].as_str().unwrap());let oracle=ttf_parser::Face::parse(&source,0).unwrap();let units=oracle.units_per_em();let count=oracle.number_of_glyphs();let expected:Vec<_>=row["text"].as_str().unwrap().chars().filter(|c|!matches!(c,'\r'|'\n')).map(|c|{let glyph=oracle.glyph_index(c).unwrap();(c,glyph.0,oracle.glyph_hor_advance(glyph).unwrap())}).collect();let pointer=source.as_ptr();let capacity=source.capacity();let mut job=FontFaceAdmissionJob::new(source,FontOutlineLimits::default());let mut work=0;loop{let p=job.advance(grant).unwrap();assert!(p.work-work<=grant as u64);work=p.work;if p.done{break;}assert!(job.result().is_err());}let font=job.take_result().unwrap();assert_eq!(font.source.as_ptr(),pointer);assert_eq!(font.face.units_per_em,units);assert_eq!(font.face.glyphs,count);for(c,glyph,advance)in expected{let mut cursor=FontCmapCursor::new(font.face,c as u32).unwrap();while !cursor.step(&font.source).unwrap(){}assert_eq!(cursor.result().unwrap(),glyph);assert_eq!(font_advance(font.face,&font.source,glyph).unwrap(),advance);}close(job);assert!(close(font)>=capacity);println!("[DEBUG] Native font {} grant={grant}: actual source pointer, Unicode and metrics match ttf-parser; physical source release funded",row["name"]);}}}
