fn font_shape_bidi_original_scalar_levels_and_physical_candidates(){use shape::unicode::{*,bidi::*,normalize::NormalizedScalar};let rows:serde_json::Value=serde_json::from_str(include_str!("../🧵️shape/🌐️unicode/↔️bidi/🧫️fixtures/🔣️.json")).unwrap();let mut admission=UnicodeDataAdmissionJob::new(UNICODE_BYTES.to_vec(),1000000);while !admission.advance(4096).unwrap().done{}let data=admission.take_result().unwrap();let data_pointer=data.source.as_ptr();for row in rows.as_array().unwrap(){let text=row["text"].as_str().unwrap();let source=semio_framework_value::list::PagedList::<_,{usize::MAX}>::try_from_iter(text.char_indices().map(|(source_at,scalar)|NormalizedScalar{scalar:scalar as u32,source_at,combining_class:0})).unwrap();let pointer=source.get(0).map(|value|value as*const NormalizedScalar);let direction=match row["direction"].as_str().unwrap(){"auto"=>UnicodeBidiDirection::Auto,"ltr"=>UnicodeBidiDirection::LeftToRight,"rtl"=>UnicodeBidiDirection::RightToLeft,_=>panic!("Unauthored direction")};for grant in [1,7,4096]{let mut cursor=UnicodeBidiCursor::new(data.layout,&data.source,&source,direction,262144,1000000000);let mut work=0;loop{let(p,physical)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.advance(&data.source,&source,grant).unwrap());assert!(!physical.overflowed);assert_eq!(physical.released_bytes,0);assert!(p.work-work<=grant as u64);work=p.work;if p.done{break;}assert!(cursor.result().is_err());}let pointer=cursor.result().unwrap().levels.get(0).map(|value|value as*const u8);let(output,physical)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.take_result().unwrap());assert_eq!((physical.requested_bytes,physical.released_bytes),(0,0));assert_eq!(output.levels.get(0).map(|value|value as*const u8),pointer);let indices=row["indices"].as_array().unwrap();assert_eq!(indices.iter().map(|value|u64::from(*output.levels.get(value.as_u64().unwrap()as usize).unwrap())).collect::<Vec<_>>(),row["levels"].as_array().unwrap().iter().map(|value|value.as_u64().unwrap()).collect::<Vec<_>>(),"{} grant={grant}",row["name"]);assert_eq!(output.order.iter().map(|value|*value as u64).collect::<Vec<_>>(),row["order"].as_array().unwrap().iter().map(|value|value.as_u64().unwrap()).collect::<Vec<_>>(),"{} grant={grant}",row["name"]);if let Some(mirrors)=row["mirrors"].as_array(){assert_eq!(output.mirrors.iter().map(|value|[value.at as u64,u64::from(value.scalar)]).collect::<Vec<_>>(),mirrors.iter().map(|value|[value[0].as_u64().unwrap(),value[1].as_u64().unwrap()]).collect::<Vec<_>>());}close(cursor);close(output);}for stop in [0,1,2,7,20,40,100]{let mut cursor=UnicodeBidiCursor::new(data.layout,&data.source,&source,direction,262144,1000000000);if stop>0{cursor.advance(&data.source,&source,stop).unwrap();}let(_,physical)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.cancel());assert_eq!((physical.requested_bytes,physical.released_bytes),(0,0));assert!(cursor.result().is_err());close(cursor);assert_eq!(source.get(0).map(|value|value as*const NormalizedScalar),pointer);assert_eq!(data.source.as_ptr(),data_pointer);}close(source);println!("[DEBUG] Native original bidi {}: independently verified shared Unicode16 levels/order/mirrors, grants1/7/4096, seven retained-source cancellations and actual physical close",row["name"]);}close(admission);close(data);}
