fn font_outline_shared_true_contours_match_ttf_parser_pixels(){let rows:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();for row in rows.as_array().unwrap(){let source=bytes(row["font"].as_str().unwrap());let pointer=source.as_ptr();let mut admission=FontFaceAdmissionJob::new(source,FontOutlineLimits::default());while !admission.advance(7).unwrap().done{}let font=admission.take_result().unwrap();for c in row["text"].as_str().unwrap().chars().filter(|c|!matches!(c,'\r'|'\n')).collect::<std::collections::BTreeSet<_>>(){let oracle=ttf_parser::Face::parse(&font.source,0).unwrap();let glyph=oracle.glyph_index(c).unwrap();let mut reference=OraclePath(tiny_skia::PathBuilder::new());oracle.outline_glyph(glyph,&mut reference);let expected=rendered(reference.0.finish(),font.face.units_per_em);for grant in [1,7,4096]{let mut cursor=outline::GlyphOutlineCursor::new(font.face,glyph.0,FontOutlineLimits::default());let mut work=0;loop{let p=cursor.advance(&font.source,grant).unwrap();assert!(p.work-work<=grant as u64);work=p.work;if p.done{break;}assert!(cursor.result().is_err());}let result=cursor.take_result().unwrap();let mut path=tiny_skia::PathBuilder::new();for segment in result.segments.iter(){match segment{crate::PathSegment::Move{to}=>path.move_to(to[0]as f32,to[1]as f32),crate::PathSegment::Line{to}=>path.line_to(to[0]as f32,to[1]as f32),crate::PathSegment::Quad{ctrl,to}=>path.quad_to(ctrl[0]as f32,ctrl[1]as f32,to[0]as f32,to[1]as f32),crate::PathSegment::Close=>path.close(),_=>panic!("Unexpected glyph curve")}}let actual=rendered(path.finish(),font.face.units_per_em);assert!(actual.data().iter().zip(expected.data()).all(|(a,b)|a.abs_diff(*b)<=1),"{} {c} grant={grant}",row["name"]);assert_eq!(font.source.as_ptr(),pointer);close(cursor);close(result);}}close(admission);close(font);println!("[DEBUG] Native true quadratic/composite font {}: ttf-parser contours and TinySkia pixels match grants 1/7/4096; original paged children physically closed",row["name"]);}}
