fn font_kerning_actual_gpos_pairs_match_rustybuzz(){let rows:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();for row in rows.as_array().unwrap(){let mut admission=FontFaceAdmissionJob::new(bytes(row["font"].as_str().unwrap()),FontOutlineLimits::default());while !admission.advance(7).unwrap().done{}let font=admission.take_result().unwrap();let oracle=rustybuzz::Face::from_slice(&font.source,0).unwrap();let text:Vec<_>=row["kerningText"].as_str().unwrap().chars().collect();for pair in text.windows(2).filter(|pair|!pair.iter().any(|c|matches!(c,'\r'|'\n'))){let mut buffer=rustybuzz::UnicodeBuffer::new();buffer.push_str(&pair.iter().collect::<String>());buffer.guess_segment_properties();let features:Vec<_>=[b"liga",b"clig",b"calt"].into_iter().map(|tag|rustybuzz::Feature{tag:ttf_parser::Tag::from_bytes(tag),value:0,start:0,end:u32::MAX}).collect();let expected=rustybuzz::shape(&oracle,&features,buffer);assert_eq!(expected.glyph_infos().len(),2);let left=expected.glyph_infos()[0].glyph_id as u16;let right=expected.glyph_infos()[1].glyph_id as u16;let reference=expected.glyph_positions().iter().map(|p|p.x_advance).sum::<i32>()-i32::from(font_advance(font.face,&font.source,left).unwrap())-i32::from(font_advance(font.face,&font.source,right).unwrap());for grant in [1,7,4096]{let mut cursor=kerning::FontKerningCursor::new(font.face,left,right,1000000000);let mut work=0;loop{let p=cursor.advance(&font.source,grant).unwrap();assert!(p.work-work<=grant as u64);work=p.work;if p.done{break;}assert!(cursor.result().is_err());}assert_eq!(cursor.result().unwrap(),reference,"{} pair={pair:?} grant={grant}",row["name"]);close(cursor);}}close(admission);close(font);println!("[DEBUG] Native real GPOS pairs {}: rustybuzz actual pair positioning matches grants 1/7/4096",row["name"]);}}
fn shape_features()->[rustybuzz::Feature;3]{[b"liga",b"clig",b"calt"].map(|tag|rustybuzz::Feature{tag:ttf_parser::Tag::from_bytes(tag),value:0,start:0,end:u32::MAX})}
struct OracleRunPath<'a>{path:&'a mut tiny_skia::PathBuilder,origin:[f64;2],scale:f64}
impl OracleRunPath<'_>{fn map(&self,x:f32,y:f32)->[f32;2]{[(self.origin[0]+f64::from(x)*self.scale)as f32,(self.origin[1]-f64::from(y)*self.scale)as f32]}}
impl ttf_parser::OutlineBuilder for OracleRunPath<'_>{fn move_to(&mut self,x:f32,y:f32){let p=self.map(x,y);self.path.move_to(p[0],p[1]);}fn line_to(&mut self,x:f32,y:f32){let p=self.map(x,y);self.path.line_to(p[0],p[1]);}fn quad_to(&mut self,x1:f32,y1:f32,x:f32,y:f32){let a=self.map(x1,y1);let b=self.map(x,y);self.path.quad_to(a[0],a[1],b[0],b[1]);}fn curve_to(&mut self,x1:f32,y1:f32,x2:f32,y2:f32,x:f32,y:f32){let a=self.map(x1,y1);let b=self.map(x2,y2);let c=self.map(x,y);self.path.cubic_to(a[0],a[1],b[0],b[1],c[0],c[1]);}fn close(&mut self){self.path.close();}}
fn path_from_segments(segments:&PagedList<crate::PathSegment,{usize::MAX}>)->Option<tiny_skia::Path>{let mut path=tiny_skia::PathBuilder::new();for segment in segments.iter(){match segment{crate::PathSegment::Move{to}=>path.move_to(to[0]as f32,to[1]as f32),crate::PathSegment::Line{to}=>path.line_to(to[0]as f32,to[1]as f32),crate::PathSegment::Quad{ctrl,to}=>path.quad_to(ctrl[0]as f32,ctrl[1]as f32,to[0]as f32,to[1]as f32),crate::PathSegment::Close=>path.close(),_=>panic!("Unexpected glyph curve")}}path.finish()}
fn rendered_run(path:Option<tiny_skia::Path>)->tiny_skia::Pixmap{let mut image=tiny_skia::Pixmap::new(512,256).unwrap();if let Some(path)=path{image.fill_path(&path,&tiny_skia::Paint::default(),tiny_skia::FillRule::Winding,tiny_skia::Transform::from_translate(8.0,8.0),None);}image}
