fn font_run_shared_multiline_outlines_match_rustybuzz_ttf_parser(){let mut unicode_admission=shape::unicode::UnicodeDataAdmissionJob::new(shape::unicode::UNICODE_BYTES.to_vec(),1000000);while !unicode_admission.advance(4096).unwrap().done{}let unicode=unicode_admission.take_result().unwrap();let rows:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();for row in rows.as_array().unwrap(){for grant in [1,7,4096]{let text=row["text"].as_str().unwrap().to_string();let text_pointer=text.as_ptr();let style=run::FontRunStyle{size:row["size"].as_f64().unwrap(),origin:[row["origin"][0].as_f64().unwrap(),row["origin"][1].as_f64().unwrap()],line_height:1.2,kerning:true};let mut admission=FontFaceAdmissionJob::new(bytes(row["font"].as_str().unwrap()),FontOutlineLimits::default());while !admission.advance(7).unwrap().done{}let fonts=[admission.take_result().unwrap()];let font_pointer=fonts[0].source.as_ptr();let parser=ttf_parser::Face::parse(&fonts[0].source,0).unwrap();let shaper=rustybuzz::Face::from_slice(&fonts[0].source,0).unwrap();let scale=style.size/f64::from(fonts[0].face.units_per_em);let mut paths=tiny_skia::PathBuilder::new();let normalized=text.replace("\r\n","\n").replace('\r',"\n");let mut expected=Vec::<(u16,[f64;2])>::new();let mut advance=0.0f64;for(line,content)in normalized.split('\n').enumerate(){let mut buffer=rustybuzz::UnicodeBuffer::new();buffer.push_str(content);buffer.guess_segment_properties();let shaped=rustybuzz::shape(&shaper,&shape_features(),buffer);let mut x=style.origin[0];let y=style.origin[1]+style.size+line as f64*style.size*style.line_height;for(info,position)in shaped.glyph_infos().iter().zip(shaped.glyph_positions()){let origin=[x+f64::from(position.x_offset)*scale,y-f64::from(position.y_offset)*scale];expected.push((info.glyph_id as u16,origin));let mut path=OracleRunPath{path:&mut paths,origin,scale};parser.outline_glyph(ttf_parser::GlyphId(info.glyph_id as u16),&mut path);x+=f64::from(position.x_advance)*scale;}advance=advance.max(x-style.origin[0]);}let reference=rendered_run(paths.finish());let mut cursor=run::FontOutlineRunCursor::new(&text,fonts.len(),style,FontOutlineLimits::default(),unicode.layout,&unicode.source);let mut work=0;loop{let p=cursor.advance(&text,&fonts,&unicode.source,grant).unwrap();assert!(p.work-work<=grant as u64);work=p.work;if p.done{break;}assert!(cursor.result().is_err());}let output=cursor.take_result().unwrap();assert_eq!(output.lines,row["expectedLines"].as_u64().unwrap()as usize);assert!((output.advance-advance).abs()<1e-8);assert_eq!(output.glyphs.len(),expected.len());for(glyph,(id,origin))in output.glyphs.iter().zip(expected){assert_eq!(glyph.glyph,id);assert!((glyph.origin[0]-origin[0]).abs()<1e-8,"{} grant={grant} glyph={id}",row["name"]);assert!((glyph.origin[1]-origin[1]).abs()<1e-8);}let actual=rendered_run(path_from_segments(&output.segments));assert!(actual.data().iter().zip(reference.data()).all(|(a,b)|a.abs_diff(*b)<=1),"{} grant={grant}",row["name"]);assert_eq!(text.as_ptr(),text_pointer);assert_eq!(fonts[0].source.as_ptr(),font_pointer);close(cursor);close(output);close(admission);let [font]=fonts;close(font);close(text);println!("[DEBUG] Native shared multiline run {} grant={grant}: rustybuzz placement, ttf-parser contours, TinySkia pixels and genuine private physical owners verified",row["name"]);}}close(unicode_admission);close(unicode);}
