fn font_run_cancellation_retains_actual_completed_children(){let mut unicode_admission=shape::unicode::UnicodeDataAdmissionJob::new(shape::unicode::UNICODE_BYTES.to_vec(),1000000);while !unicode_admission.advance(4096).unwrap().done{}let unicode=unicode_admission.take_result().unwrap();let text="Grüße AV To".to_string();let mut admission=FontFaceAdmissionJob::new(bytes("🚀️anta/🏛️latin/📖️regular"),FontOutlineLimits::default());while !admission.advance(7).unwrap().done{}let fonts=[admission.take_result().unwrap()];let style=run::FontRunStyle{size:24.0,origin:[0.0;2],line_height:1.2,kerning:true};for stop in [0,1,2,7,20,100,1000,10000]{let mut cursor=run::FontOutlineRunCursor::new(&text,1,style,FontOutlineLimits::default(),unicode.layout,&unicode.source);if stop>0{cursor.advance(&text,&fonts,&unicode.source,stop).unwrap();}cursor.cancel();assert!(cursor.result().is_err());close(cursor);}let missing="\u{10ffff}";let mut cursor=run::FontOutlineRunCursor::new(missing,1,style,FontOutlineLimits::default(),unicode.layout,&unicode.source);assert!(cursor.advance(missing,&fonts,&unicode.source,10000).is_err());close(cursor);close(admission);let [font]=fonts;close(font);close(text);println!("[DEBUG] Native run cancellation at eight stages and unsupported Unicode retains actual completed child allocations until funded close");close(unicode_admission);close(unicode);}
