fn font_catalog_shared_family_requests_preserve_actual_sources(){let policy:serde_json::Value=serde_json::from_str(include_str!("../📇️catalog/🧫️fixtures/🔣️.json")).unwrap();assert_eq!(policy["defaultFamily"],catalog::DEFAULT_FAMILY);for family in policy["families"].as_array().unwrap(){let family=family.as_str().unwrap();let mut job=catalog::FontCatalogAdmissionJob::new(family,400,FontOutlineLimits::default());while !job.advance(7).unwrap().done{}let output=job.take_result().unwrap();let sources:Vec<_>=catalog::FONT_SOURCES.iter().filter(|row|row.family==family).chain(catalog::FONT_SOURCES.iter().filter(|row|family!="Noto Emoji"&&row.family=="Noto Emoji")).collect();assert_eq!(sources.len(),output.len());assert_eq!(sources[0].family,family);for(font,source)in output.iter().zip(sources){assert_eq!(font.source.0.as_ptr(),source.bytes.0.as_ptr());let oracle=ttf_parser::Face::parse(source.bytes.0,0).unwrap();assert_eq!(font.face.glyphs,oracle.number_of_glyphs());assert_eq!(font.face.units_per_em,oracle.units_per_em());}close(job);close(output);println!("[DEBUG] Native explicit family {family}: actual immutable sources and declared emoji fallback agree with ttf-parser and physical close");}for(family,weight)in[("Unsupported Font",400),("Anta",700)]{let mut job=catalog::FontCatalogAdmissionJob::new(family,weight,FontOutlineLimits::default());assert!(job.advance(1).is_err());assert!(job.result().is_err());close(job);}}

