fn font_shape_lookup_authority_matches_independent_ttf_parser(){let features=[*b"ccmp",*b"rlig",*b"liga",*b"clig",*b"calt",*b"kern",*b"mark",*b"mkmk"];for source in catalog::FONT_SOURCES.iter(){let mut admission=FontFaceAdmissionJob::new(source.bytes,FontOutlineLimits::default());while !admission.advance(7).unwrap().done{}let font=admission.take_result().unwrap();let parser=ttf_parser::Face::parse(source.bytes.0,0).unwrap();for substitution in [true,false]{let table=if substitution{parser.tables().gsub}else{parser.tables().gpos};let language=table.and_then(|table|table.scripts.find(ttf_parser::Tag::from_bytes(b"latn")).or_else(||table.scripts.find(ttf_parser::Tag::from_bytes(b"DFLT"))).and_then(|script|script.default_language));let mut expected=std::collections::BTreeSet::new();if let(Some(table),Some(language))=(table,language){for index in language.required_feature.into_iter().chain(language.feature_indices){let feature=table.features.get(index).unwrap();if language.required_feature==Some(index)||features.iter().any(|tag|feature.tag==ttf_parser::Tag::from_bytes(tag)){expected.extend(feature.lookup_indices);}}}for grant in [1,7,4096]{let mut cursor=shape::FontLookupPlanCursor::new(font.face,substitution,*b"latn",&features,1000000000);let mut work=0;loop{let p=cursor.advance(source.bytes.0,grant).unwrap();assert!(p.work-work<=grant as u64);work=p.work;if p.done{break;}assert!(cursor.result().is_err());}let output=cursor.take_result().unwrap();assert_eq!(output.iter().map(|lookup|lookup.index).collect::<Vec<_>>(),expected.iter().copied().collect::<Vec<_>>());for lookup in output.iter(){let oracle=table.unwrap().lookups.get(lookup.index).unwrap();assert_eq!(lookup.flags,oracle.flags.0);assert_eq!(lookup.subtables,usize::from(oracle.subtables.len()));}close(cursor);close(output);}for stop in [0,1,2,7,20,40,100]{let mut cursor=shape::FontLookupPlanCursor::new(font.face,substitution,*b"latn",&features,1000000000);if stop>0{cursor.advance(source.bytes.0,stop).unwrap();}cursor.cancel();assert!(cursor.result().is_err());close(cursor);}}close(admission);close(font);println!("[DEBUG] Original native layout {}/{}: ttf-parser feature order/flags, grants 1/7/4096, seven interruptions and physical owner close",source.family,source.id);}}
