fn font_shape_original_ligature_matches_rustybuzz(){let rows:serde_json::Value=serde_json::from_str(include_str!("../🧵️shape/🧫️fixtures/🔣️.json")).unwrap();let row=rows.as_array().unwrap().iter().find(|row|row["name"]=="Joined Emoji Profession").unwrap();let source=bytes(row["font"].as_str().unwrap());let mut admission=FontFaceAdmissionJob::new(source,FontOutlineLimits::default());while !admission.advance(7).unwrap().done{}let font=admission.take_result().unwrap();let parser=ttf_parser::Face::parse(&font.source,0).unwrap();let input=row["text"].as_str().unwrap().chars().map(|scalar|parser.glyph_index(scalar).unwrap().0).collect::<Vec<_>>();let mut buffer=rustybuzz::UnicodeBuffer::new();buffer.push_str(row["text"].as_str().unwrap());buffer.guess_segment_properties();let oracle=rustybuzz::shape(&rustybuzz::Face::from_slice(&font.source,0).unwrap(),&[],buffer);assert_eq!(oracle.glyph_infos().len(),1);let expected=oracle.glyph_infos()[0].glyph_id as u16;let mut plan=shape::FontLookupPlanCursor::new(font.face,true,*b"DFLT",&[*b"ccmp"],1000000000);while !plan.advance(&font.source,7).unwrap().done{}let output=plan.take_result().unwrap();for grant in [1,7,4096]{let mut matched=false;for lookup in output.iter().filter(|lookup|lookup.kind==4&&lookup.flags==0){let mut cursor=shape::ligature::FontLigatureCursor::new(font.face,*lookup,&input,0,1000000000);let mut work=0;loop{let p=cursor.advance(&font.source,&input,grant).unwrap();assert!(p.work-work<=grant as u64);work=p.work;if p.done{break;}assert!(cursor.result().is_err());}if let Some(result)=cursor.result().unwrap(){assert_eq!(result,shape::ligature::FontLigatureMatch{glyph:expected,consumed:input.len()});matched=true;}close(cursor);for stop in [0,1,2,7,20,40,100]{let mut cancelled=shape::ligature::FontLigatureCursor::new(font.face,*lookup,&input,0,1000000000);if stop>0{cancelled.advance(&font.source,&input,stop).unwrap();}cancelled.cancel();assert!(cancelled.result().is_err());close(cancelled);}}assert!(matched);}close(plan);close(output);close(input);close(admission);close(font);println!("[DEBUG] Native original profession emoji: exact actual rustybuzz ligature, grants 1/7/4096, seven interruptions and funded physical owner close");}
