fn font_shape_original_mark_matches_ttf_parser(){let mut admission=FontFaceAdmissionJob::new(bytes("🚀️anta/🏛️latin/📖️regular"),FontOutlineLimits::default());while !admission.advance(7).unwrap().done{}let font=admission.take_result().unwrap();let parser=ttf_parser::Face::parse(&font.source,0).unwrap();println!("[DEBUG] Actual covered mark scalar {:?}",(0x300..=0x36f).filter_map(char::from_u32).find(|scalar|parser.glyph_index(*scalar)==Some(ttf_parser::GlyphId(214))));let mut plan=shape::FontLookupPlanCursor::new(font.face,false,*b"latn",&[*b"mark"],1000000000);while !plan.advance(&font.source,7).unwrap().done{}let output=plan.take_result().unwrap();let mut tested=0;for lookup in output.iter().filter(|lookup|lookup.kind==4&&lookup.flags==0){let parsed=parser.tables().gpos.unwrap().lookups.get(lookup.index).unwrap();let ttf_parser::gpos::PositioningSubtable::MarkToBase(table)=parsed.subtables.get::<ttf_parser::gpos::PositioningSubtable>(0).unwrap()else{panic!("Expected mark-to-base");};let(base,base_index)=(0..font.face.glyphs).find_map(|glyph|table.base_coverage.get(ttf_parser::GlyphId(glyph)).map(|index|(glyph,index))).unwrap();let(mark,mark_index)=(0..font.face.glyphs).find_map(|glyph|table.mark_coverage.get(ttf_parser::GlyphId(glyph)).map(|index|(glyph,index))).unwrap();let(class,anchor)=table.marks.get(mark_index).unwrap();let reference=table.anchors.get(base_index,class).unwrap();let expected=shape::mark::FontMarkAttachment{x:i32::from(reference.x)-i32::from(anchor.x),y:i32::from(reference.y)-i32::from(anchor.y)};for grant in [1,7,4096]{let mut cursor=shape::mark::FontMarkCursor::new(font.face,*lookup,base,mark,1000000000);let mut work=0;loop{let p=cursor.advance(&font.source,grant).unwrap();assert!(p.work-work<=grant as u64);work=p.work;if p.done{break;}assert!(cursor.result().is_err());}assert_eq!(cursor.result().unwrap(),Some(expected));close(cursor);for stop in [0,1,2,7,20,40,100]{let mut cancelled=shape::mark::FontMarkCursor::new(font.face,*lookup,base,mark,1000000000);if stop>0{cancelled.advance(&font.source,stop).unwrap();}cancelled.cancel();assert!(cancelled.result().is_err());close(cancelled);}}tested+=1;println!("[DEBUG] Native original mark: glyphs=({base},{mark}), independent ttf-parser anchor delta=({},{}), grants 1/7/4096 and seven interruptions physically closed",expected.x,expected.y);}assert!(tested>0);close(plan);close(output);close(admission);close(font);}#[test]
fn font_shape_unicode_original_records_and_physical_source(){use shape::unicode::*;let corpus:serde_json::Value=serde_json::from_str(include_str!("../🧵️shape/🌐️unicode/🧫️fixtures/🔣️.json")).unwrap();let provenance:serde_json::Value=serde_json::from_str(include_str!("../🧵️shape/🌐️unicode/📦️data/🔣️provenance.json")).unwrap();for grant in [1,7,4096]{let source=UNICODE_BYTES.to_vec();let pointer=source.as_ptr();let capacity=source.capacity();let mut admission=UnicodeDataAdmissionJob::new(source,1000000);let mut work=0;loop{let p=admission.advance(grant).unwrap();assert!(p.work-work<=grant as u64);work=p.work;if p.done{break;}assert!(admission.result().is_err());}let data=admission.take_result().unwrap();assert_eq!(data.source.as_ptr(),pointer);for row in corpus["properties"].as_array().unwrap(){let mut cursor=UnicodePropertyCursor::new(data.layout,row["scalar"].as_u64().unwrap()as u32).unwrap();while !cursor.step(&data.source).unwrap(){}let property=cursor.result().unwrap();assert_eq!(provenance["categories"][usize::from(property.category)],row["category"]);assert_eq!(provenance["bidiClasses"][usize::from(property.bidi)],row["bidi"]);assert_eq!(u64::from(property.combining_class),row["combiningClass"].as_u64().unwrap());close(cursor);}let r=FontReader::whole(&data.source);for row in corpus["compositions"].as_array().unwrap(){let mut cursor=UnicodeMappingCursor::new(data.layout,UnicodeMapping::Composition,row["first"].as_u64().unwrap()as u32,row["second"].as_u64().unwrap()as u32);while !cursor.step(&data.source).unwrap(){}assert_eq!(u64::from(r.u32(cursor.result().unwrap().unwrap()+8).unwrap()),row["result"].as_u64().unwrap());close(cursor);}for row in corpus["decompositions"].as_array().unwrap(){let mut cursor=UnicodeMappingCursor::new(data.layout,UnicodeMapping::Decomposition,row["scalar"].as_u64().unwrap()as u32,0);while !cursor.step(&data.source).unwrap(){}let at=cursor.result().unwrap().unwrap();let first=r.u32(at+4).unwrap()as usize;let count=r.u32(at+8).unwrap()as usize;assert_eq!((0..count).map(|index|u64::from(r.u32(data.layout.offsets[3]+(first+index)*4).unwrap())).collect::<Vec<_>>(),row["values"].as_array().unwrap().iter().map(|value|value.as_u64().unwrap()).collect::<Vec<_>>());assert_eq!(r.u32(at+12).unwrap()!=0,row["compatibility"].as_bool().unwrap());close(cursor);}close(admission);assert!(close(data)>=capacity);println!("[DEBUG] Native Unicode16 grant={grant}: {work} actual immutable records, shared property/composition/decomposition vectors, original pointer and funded physical source close");}for stop in [0,1,2,7,20,100,20000]{let source=UNICODE_BYTES.to_vec();let capacity=source.capacity();let mut job=UnicodeDataAdmissionJob::new(source,1000000);if stop>0{job.advance(stop).unwrap();}let(_,physical)=semio_framework_trace::observe_heap_allocations_on_this_thread(||job.cancel());assert_eq!((physical.requested_bytes,physical.released_bytes),(0,0));assert!(job.result().is_err());assert!(close(job)>=capacity);}println!("[DEBUG] Native Unicode16 seven cancelled original byte owners retained through actual physical close");}
