fn font_shape_whole_cluster_original_source_selection(){use shape::{face::*,unicode::{*,normalize::NormalizedScalar,cluster::UnicodeCluster}};let rows:serde_json::Value=serde_json::from_str(include_str!("../🧵️shape/📇️face/🧫️fixtures/🔣️.json")).unwrap();let mut unicode_admission=UnicodeDataAdmissionJob::new(UNICODE_BYTES.to_vec(),1000000);while !unicode_admission.advance(4096).unwrap().done{}let data=unicode_admission.take_result().unwrap();for row in rows.as_array().unwrap(){let mut catalog=catalog::FontCatalogAdmissionJob::new(row["family"].as_str().unwrap(),400,FontOutlineLimits::default());while !catalog.advance(4096).unwrap().done{}let fonts=catalog.take_result().unwrap();let original=semio_framework_value::list::PagedList::<_,{usize::MAX}>::try_from_iter(row["text"].as_str().unwrap().char_indices().map(|(source_at,scalar)|NormalizedScalar{scalar:scalar as u32,source_at,combining_class:0})).unwrap();let parsed=fonts.iter().map(|font|ttf_parser::Face::parse(font.source.0,0).unwrap()).collect::<Vec<_>>();let resolve=|font:&ttf_parser::Face<'_>,value:&NormalizedScalar,index:usize|{if let Some(glyph)=font.glyph_index(char::from_u32(value.scalar).unwrap()){return Some(vec![glyph.0]);}if matches!(value.scalar,0x200d|0xfe0f){return Some(vec![0]);}row["alternates"][index].as_str().unwrap().chars().map(|scalar|font.glyph_index(scalar).map(|glyph|glyph.0)).collect::<Option<Vec<_>>>()};let expected=parsed.iter().position(|font|original.iter().enumerate().all(|(index,value)|resolve(font,value,index).is_some()));assert_eq!(expected.is_none(),row["refuses"].as_bool().unwrap());let cluster=UnicodeCluster{start:0,end:original.len()};for grant in [1,7,4096]{let mut cursor=FontClusterFaceCursor::new(data.layout,&data.source,&original,&fonts,cluster,0,FontOutlineLimits::default());let mut work=0;let result=loop{match cursor.advance(&data.source,&original,&fonts,grant){Ok(p)=>{assert!(p.work-work<=grant as u64);work=p.work;if p.done{break true;}assert!(cursor.result().is_err());},Err(error)=>{assert_eq!(error,"Unicode grapheme has no single admitted font source");break false;}}};assert_eq!(result,expected.is_some());if let Some(expected)=expected{let pointer=cursor.result().unwrap().glyphs.as_ptr();let output=cursor.take_result().unwrap();assert_eq!(output.face,expected);assert_eq!(output.glyphs.as_ptr(),pointer);let mapped=original.iter().enumerate().flat_map(|(index,source)|resolve(&parsed[expected],source,index).unwrap().into_iter().map(move|glyph|(glyph,source.source_at))).collect::<Vec<_>>();assert_eq!(output.glyphs.len(),mapped.len());for(value,(glyph,source_at))in output.glyphs.iter().zip(mapped){assert_eq!(value.glyph,glyph);assert_eq!(value.source_at,source_at);}close(cursor);close(output);}else{assert!(cursor.result().is_err());close(cursor);}}for stop in [0,1,2,7,20,100,1000]{let mut cursor=FontClusterFaceCursor::new(data.layout,&data.source,&original,&fonts,cluster,0,FontOutlineLimits::default());if stop>0{let _=cursor.advance(&data.source,&original,&fonts,stop);}let(_,physical)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.cancel());assert_eq!((physical.requested_bytes,physical.released_bytes),(0,0));assert!(cursor.result().is_err());close(cursor);}drop(parsed);close(original);close(catalog);close(fonts);println!("[DEBUG] Native whole font cluster {}: independent ttf-parser first full source={expected:?}, original output Vec identity, all grants and seven physical interruption receipts",row["name"]);}close(unicode_admission);close(data);}

