fn font_shape_shared_repeated_gap_edits(){use shape::face::{FontClusterMapping,FontMappedScalar};let rows:serde_json::Value=serde_json::from_str(include_str!("../🧵️shape/🧩️context/🪄️apply/🧫️fixtures/🔣️.json")).unwrap();let mut limits=FontOutlineLimits::default();limits.max_glyphs=4096;let mut admission=FontFaceAdmissionJob::new(bytes(rows[0]["font"].as_str().unwrap()),limits);while !admission.advance(4096).unwrap().done{}let font=admission.take_result().unwrap();let parser=ttf_parser::Face::parse(&font.source,0).unwrap();for row in rows.as_array().unwrap(){let repeat=row["repeat"].as_u64().unwrap()as usize;let text=row["text"].as_str().unwrap().repeat(repeat);let original=||FontClusterMapping{face:0,glyphs:text.char_indices().map(|(source_at,scalar)|FontMappedScalar{glyph:parser.glyph_index(scalar).unwrap().0,scalar:scalar as u32,source_at:source_at/8*8,property:shape::unicode::UnicodeProperty{combining_class:0,category:28,bidi:0,joining:0,grapheme:12,flags:0,script:0}}).collect()};let mut buffer=rustybuzz::UnicodeBuffer::new();buffer.push_str(&text);buffer.guess_segment_properties();let oracle=rustybuzz::shape(&rustybuzz::Face::from_slice(&font.source,0).unwrap(),&[],buffer);let expected=oracle.glyph_infos().iter().map(|glyph|glyph.glyph_id as u16).collect::<Vec<_>>();assert_eq!(expected,vec![row["glyphs"][0].as_u64().unwrap()as u16;repeat]);let grants: &[usize]=if repeat>64{&[4096]}else{&[1,7,4096]};for &grant in grants{let mut cursor=shape::layout::FontClusterLayoutCursor::new(font.face,original(),limits);let mut work=0;loop{let(progress,physical)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.advance(&font.source,grant).unwrap());assert!(!physical.overflowed);assert_eq!(physical.released_bytes,0);assert!(progress.work-work<=grant as u64);work=progress.work;if progress.done{break;}}assert!(work<(repeat*20000+4096*8)as u64);let pointer=cursor.result().unwrap().glyphs.as_ptr();let(output,physical)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.take_result().unwrap());assert_eq!((physical.requested_bytes,physical.released_bytes),(0,0));assert_eq!(output.glyphs.as_ptr(),pointer);assert_eq!(output.glyphs.iter().map(|glyph|glyph.glyph).collect::<Vec<_>>(),expected);close_with_items(cursor,if repeat>64{64}else{1});assert_eq!(output.glyphs.as_ptr(),pointer);close(output);println!("[DEBUG] Original nested gap {} grant={grant}: glyphs={repeat} work={work}, actual Rustybuzz output, zero normal-work heap release, original allocation handoff and funded physical close",row["name"]);}for stop in row["stops"].as_array().unwrap(){let mut cursor=shape::layout::FontClusterLayoutCursor::new(font.face,original(),limits);let stop=stop.as_u64().unwrap()as usize;if stop>0{cursor.advance(&font.source,stop).unwrap();}let(_,physical)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.cancel());assert_eq!((physical.requested_bytes,physical.released_bytes),(0,0));assert!(cursor.result().is_err());close(cursor);}}close(admission);close(font);}
